1	export type TicketCategoryPricing = {
2	  priceWeekday: number;
3	  priceHoliday: number;
4	  memberPrice: number;
5	};
6	
7	// Member price selalu menang, tidak peduli hari libur atau bukan — sama
8	// seperti checkout_ticket_transaction di database (lihat migration
9	// 20260706200000_ticket_venue.sql).
10	export function ticketUnitPrice(
11	  category: TicketCategoryPricing,
12	  opts: { isMember: boolean; isHoliday: boolean },
13	): number {
14	  if (opts.isMember) return category.memberPrice;
15	  return opts.isHoliday ? category.priceHoliday : category.priceWeekday;
16	}
