18	export type TicketCartLine = {
19	  unitPrice: number;
20	  qty: number;
21	};
22	
23	export type TicketTotals = {
24	  subtotal: number;
25	  serviceAmt: number;
26	  taxAmt: number;
27	  total: number;
28	};
29	
30	export function calculateTicketTotals(params: {
31	  lines: TicketCartLine[];
32	  serviceRate: number;
33	  taxRate: number;
34	}): TicketTotals {
35	  const { lines, serviceRate, taxRate } = params;
36	
37	  const subtotal = lines.reduce((sum, l) => sum + l.unitPrice * l.qty, 0);
38	  const serviceAmt = serviceRate > 0 ? Math.round((subtotal * serviceRate) / 100) : 0;
39	  const taxAmt = taxRate > 0 ? Math.round(((subtotal + serviceAmt) * taxRate) / 100) : 0;
40	  const total = subtotal + serviceAmt + taxAmt;
41	
42	  return { subtotal, serviceAmt, taxAmt, total };
43	}
