1	import { describe, expect, it } from "vitest";
2	import { calculateTicketTotals, ticketUnitPrice } from "./ticket-checkout-totals";
3	
4	const category = { priceWeekday: 25000, priceHoliday: 35000, memberPrice: 0 };
5	
6	describe("ticketUnitPrice", () => {
7	  it("uses the weekday price on a regular day", () => {
8	    expect(ticketUnitPrice(category, { isMember: false, isHoliday: false })).toBe(25000);
9	  });
10	
11	  it("uses the holiday price on a holiday", () => {
12	    expect(ticketUnitPrice(category, { isMember: false, isHoliday: true })).toBe(35000);
13	  });
14	
15	  it("uses the member price regardless of holiday", () => {
16	    expect(ticketUnitPrice(category, { isMember: true, isHoliday: false })).toBe(0);
17	    expect(ticketUnitPrice(category, { isMember: true, isHoliday: true })).toBe(0);
18	  });
19	});
20	
21	describe("calculateTicketTotals", () => {
22	  it("sums unit price times qty across lines, then service, then tax", () => {
23	    // 2x 25000 + 1x 10000 = 60000, 5% service = 3000 -> 63000, 10% tax = 6300
24	    const totals = calculateTicketTotals({
25	      lines: [
26	        { unitPrice: 25000, qty: 2 },
27	        { unitPrice: 10000, qty: 1 },
28	      ],
29	      serviceRate: 5,
30	      taxRate: 10,
31	    });
32	
33	    expect(totals.subtotal).toBe(60000);
34	    expect(totals.serviceAmt).toBe(3000);
35	    expect(totals.taxAmt).toBe(6300);
36	    expect(totals.total).toBe(69300);
37	  });
38	
39	  it("returns zero totals for an empty cart", () => {
40	    const totals = calculateTicketTotals({ lines: [], serviceRate: 5, taxRate: 10 });
41	
42	    expect(totals.subtotal).toBe(0);
43	    expect(totals.total).toBe(0);
44	  });
45	
46	  it("skips service and tax when both rates are disabled", () => {
47	    const totals = calculateTicketTotals({
48	      lines: [{ unitPrice: 25000, qty: 1 }],
49	      serviceRate: 0,
50	      taxRate: 0,
51	    });
52	
53	    expect(totals.serviceAmt).toBe(0);
54	    expect(totals.taxAmt).toBe(0);
55	    expect(totals.total).toBe(25000);
56	  });
57	
58	  it("computes tax on subtotal plus service, not subtotal alone", () => {
59	    const totals = calculateTicketTotals({
60	      lines: [{ unitPrice: 100000, qty: 1 }],
61	      serviceRate: 10,
62	      taxRate: 10,
63	    });
64	
65	    // service = 10000 -> 110000, tax = 11000 (not 10000)
66	    expect(totals.serviceAmt).toBe(10000);
67	    expect(totals.taxAmt).toBe(11000);
68	    expect(totals.total).toBe(121000);
69	  });
70	});
